import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {compileBinaryProject} from '../packages/binary-project/index.js';
import {compileProject} from '../packages/project-system/index.js';
import {createRuntime} from '../packages/avalonia-runtime/index.js';
import {createCombinedSourceMap} from '../packages/development/source-map.js';
const fixture=new URL('./fixtures/pdb/',import.meta.url);
async function inputs(){const [dll,pdb,sources]=await Promise.all([readFile(new URL('Probe.dll.base64',fixture),'utf8'),readFile(new URL('Probe.pdb.base64',fixture),'utf8'),readFile(new URL('sources.json',fixture),'utf8')]);return [{name:'Probe.dll',data:dll.trim()},{name:'Probe.pdb',data:pdb.trim()},...Object.entries(JSON.parse(sources)).map(([name,text])=>({name,text}))];}
function successful(result){assert.equal(result.success,true,JSON.stringify(result.diagnostics));return result;}
test('matching Portable PDB exposes original CSharp source sequence points',async()=>{const r=successful(await compileBinaryProject(await inputs(),{debug:true}));assert.ok(r.debug.sites.length>0);assert.ok(r.debug.sites.some(p=>p.file.endsWith('Probe.cs')&&p.origin==='msil'));assert.ok(Object.keys(r.debug.sources).some(p=>p.endsWith('Probe.cs')));assert.match(r.code,/R\.debugHit/);});
test('original source whose checksum changed blocks binary debug compilation',async()=>{const files=await inputs();const source=files.find(f=>f.name.endsWith('Probe.cs'));assert.ok(source);source.text+='\n// altered source';const r=await compileBinaryProject(files,{debug:true});assert.equal(r.success,false);assert.ok(r.diagnostics.some(d=>d.severity==='error'));});
test('truncated PDB is a diagnostic rather than executable output',async()=>{const files=await inputs();files.find(f=>f.name.endsWith('.pdb')).data='AA==';const r=await compileBinaryProject(files,{debug:true});assert.equal(r.success,false);assert.ok(r.diagnostics.some(d=>d.severity==='error'));});
test('release conversion strips binary debug hooks and symbol metadata',async()=>{const r=successful(await compileBinaryProject(await inputs(),{debug:false}));assert.equal(r.debug,undefined);assert.doesNotMatch(r.code,/R\.debugHit|\/\*@jb:/);});
test('DLL without PDB does not invent source sequence points',async()=>{const files=await inputs();const r=successful(await compileBinaryProject(files.filter(f=>f.name.endsWith('.dll')),{debug:true}));assert.equal(r.debug.sites.length,0);assert.equal(Object.keys(r.debug.sources).length,0);});
test('hidden PDB points do not become user breakpoint sites',async()=>{const r=successful(await compileBinaryProject(await inputs(),{debug:true}));assert.ok(r.debug.sites.length);for(const p of r.debug.sites){assert.notEqual(p.hidden,true);assert.ok(p.line>0);assert.ok(p.column>0);}});
test('symbol-bearing NuGet uses the same verified source debugging path',async()=>{const data=(await readFile(new URL('Probe.1.0.0.nupkg.base64',fixture),'utf8')).trim();const r=successful(await compileBinaryProject([{name:'Probe.1.0.0.nupkg',data}],{debug:true,targetFramework:'net8.0'}));assert.ok(r.debug.sites.length);assert.ok(Object.keys(r.debug.sources).some(p=>p.endsWith('Probe.cs')));});
test('combined source maps accept namespaced binary markers without numeric collisions',()=>{const map=createCombinedSourceMap('/*@jb:il:7*/if(R.debugHit()){debugger;}\nreturn 1;',[{id:'il:7',file:'Library.cs',line:4,column:2}],{'Library.cs':'// original source'});assert.equal(map.version,3);assert.deepEqual(map.sourcesContent,['// original source']);assert.ok(map.mappings.length);});
test('static library method called Sum is not lowered as LINQ',()=>{const r=compileProject({'Entry.cs':'public class Numbers { public static int Sum(int n){return n+10;} } public class Entry {public static int Run(){return Numbers.Sum(4);}}'});successful(r);const JB=createRuntime();new Function('JB',r.code)(JB);assert.equal(JB.types.get('Entry').Run(),14);});
